Widget _table(List<String> headers,List<List<dynamic>> rows)=>SingleChildScrollView(scrollDirection:Axis.horizontal,child:DataTable(headingRowColor:WidgetStatePropertyAll(Colors.grey.shade100),columns:headers.map((h)=>DataColumn(label:Text(h,style:const TextStyle(fontWeight:FontWeight.bold)))).toList(),rows:rows.map((r)=>DataRow(cells:r.map((v)=>DataCell(v is Widget?v:Text(v.toString()))).toList())).toList()));
Widget _badge(String s)=>Chip(label:Text(s),visualDensity:VisualDensity.compact);
class _ErrorBox extends StatelessWidget{const _ErrorBox(this.message);final String message;@override Widget build(BuildContext c)=>Card(color:Colors.red.shade50,child:Padding(padding:const EdgeInsets.all(12),child:Text(message,style:TextStyle(color:Colors.red.shade900))));}
String _clean(Object e){ if(e is ApiException) return e.message; final s=e.toString(); return s.contains('<html')?'Request failed. Please try again or contact support.':s; }
Future<bool> _confirm(BuildContext context,String msg) async => await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Confirm'),content:Text(msg),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Confirm'))]))??false;
Future<void> _reverseDialog(BuildContext context,AccountingService service,String id,VoidCallback done) async{final date=TextEditingController(text:DateTime.now().toIso8601String().substring(0,10));final reason=TextEditingController();await showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Reverse Journal'),content:SizedBox(width:420,child:Column(mainAxisSize:MainAxisSize.min,children:[const Text('The original journal will not be deleted. A new reversing journal will be created. This action must be auditable.'),TextField(controller:date,decoration:const InputDecoration(labelText:'Reversal Date')),TextField(controller:reason,decoration:const InputDecoration(labelText:'Reason'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()async{final res=await service.reverseJournal(id,{'reversal_date':date.text,'reason':reason.text});if(c.mounted){Navigator.pop(c);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Reversal journal ${res['journal_no']??res['reversal_journal_no']??''} created.')));done();}},child:const Text('Confirm Reversal'))]));}
